    padding: 16px;
  }
  
  .balance-card {
    flex-direction: column;
    gap: 12px;
  }
  
  .add-form {
    flex-direction: column;
  }
  
  .add-form select,
  .add-form input,
  .add-form button {
    width: 100%;
  }
