<style>.expense-tracker {
  max-width: 550px;
  margin: 40px auto;
  padding: 24px;
  background: #ffffff;
  border-radius: 20px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
  transition: all 0.3s;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.expense-tracker.dark-mode {
  background: #1e293b;
  color: #e2e8f0;
}

/* 头部 */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.header h2 {
  margin: 0;
}

.theme-btn {
  padding: 8px 16px;
  background: #f1f5f9;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 16px;
}

.dark-mode .theme-btn {
  background: #334155;
}

/* 余额卡片 */
.balance-card {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
  padding: 16px;
  background: #f8fafc;
  border-radius: 16px;
}

.dark-mode .balance-card {
  background: #0f172a;
}

.balance-item {
  flex: 1;
  text-align: center;
}

.balance-label {
  display: block;
  font-size: 12px;
  color: #64748b;
  margin-bottom: 8px;
}

.balance-value {
  display: block;
  font-size: 20px;
  font-weight: 700;
}

.balance-value.income {
  color: #10b981;
}

.balance-value.expense {
  color: #ef4444;
}

.balance-value.positive {
  color: #10b981;
}

.balance-value.negative {
  color: #ef4444;
}

/* 添加表单 */
.add-form {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.add-form select,
.add-form input {
  padding: 10px 12px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  font-size: 14px;
  background: white;
}

.dark-mode .add-form select,
.dark-mode .add-form input {
  background: #0f172a;
  border-color: #334155;
  color: #e2e8f0;
}

.add-form select {
  width: 80px;
}

.add-form input:first-of-type {
  width: 100px;
}

.add-form input:last-of-type {
  width: 120px;
}

.add-form button {
  padding: 10px 20px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 600;
}

/* 筛选栏 */
.filter-bar {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.filter-bar select {
  padding: 8px 12px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: white;
  cursor: pointer;
}

.dark-mode .filter-bar select {
  background: #0f172a;
  border-color: #334155;
  color: #e2e8f0;
}

.clear-filter {
  padding: 8px 16px;
  background: #f1f5f9;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 12px;
}

/* 图表区域 */
.chart-section {
  margin-bottom: 24px;
  padding: 16px;
  background: #f8fafc;
  border-radius: 16px;
}

.dark-mode .chart-section {
  background: #0f172a;
}

.chart-section h3 {
  margin: 0 0 16px 0;
  font-size: 14px;
}

.chart-bars {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.chart-item {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
}

.chart-label {
  width: 50px;
  font-weight: 500;
}

.bar-container {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar {
  height: 8px;
  background: #3b82f6;
  border-radius: 4px;
  transition: width 0.3s;
}

.bar-value {
  font-size: 12px;
  color: #64748b;
  min-width: 45px;
}

/* 记录列表 */
.records-list {
  margin-bottom: 16px;
  max-height: 350px;
  overflow-y: auto;
}

.record-item {
  display: flex;
